function [dist] = levenshtein_distance(str1,str2)
    m = length(str1);
    n = length(str2);
    d = zeros(m+1,n+1);
    for i=1:m+1
        d(i,1) = i-1;
    end
    for j=1:n+1
        d(1,j) = j-1;
    end
    for j=2:n+1
        for i=2:m+1
            if str1(i-1) == str2(j-1)
