```c++
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;
int countAlliterations(string text) {
    vector<char> firstLetters;
    int count = 0;
    transform(text.begin(), text.end(), text.begin(), ::tolower);
    for (int i = 0; i < text.length(); i++) {
        if (isalpha(text[i])) {
            if (i == 0 || text[i-1] == ' ' || text[i-1] == '-') {
                firstLetters.push_back(text[i]);
            } else if (text[i] == firstLetters.back()) {
                count++;
            } else {
                firstLetters.clear();
                firstLetters.push_back(text[i]);
            }
        }
    }
    return count;
}
int main() {
