        System.out.println("Excerpt 2 average sentence length: " + sentLength2);
        System.out.println("Excerpt 1 metaphor count: " + metaphorCount1);
        System.out.println("Excerpt 2 metaphor count: " + metaphorCount2);
    }
    private static int countAdjectives(String text) {
        Pattern pattern = Pattern.compile("\\b([A-Z][a-z]*\\s)?([A-Z][a-z]*\\s)?([A-Z][a-z]*)\\b");
        Matcher matcher = pattern.matcher(text);
        int count = 0;
        while (matcher.find()) {
            count++;
        }
        return count;
    }
    private static int getAverageSentenceLength(String text) {
        String[] sentences = text.split("[.?!]");
        int totalLength = 0;
        for (String sentence : sentences) {
            totalLength += sentence.trim().split("\\s+").length;
        }
        return totalLength / sentences.length;
    }
    private static int countMetaphors(String text) {
        int count = 0;
        Document doc = new Document(text);
        for (Sentence sent : doc.sentences()) {
            for (int i = 0; i < sent.mentions().size(); i++) {
                if (sent.mentions().get(i).entityType().equals("METAPHOR")) {
                    count++;
                }
            }
        }
        return count;
    }
}
