        double[,] ATA = Multiply(AT, A);
        double[] ATB = Multiply(AT, B);
        double[] coeffs = Solve(ATA, ATB);
        Console.WriteLine("Polynomial equation: y = {0} + {1}x + {2}x^2", coeffs[0], coeffs[1], coeffs[2]);
    }
    public static double[,] Transpose(double[,] matrix)
    {
        int rows = matrix.GetLength(0);
        int cols = matrix.GetLength(1);
        double[,] result = new double[cols, rows];
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                result[j, i] = matrix[i, j];
            }
        }
        return result;
    }
    public static double[,] Multiply(double[,] matrix1, double[,] matrix2)
    {
        int rows1 = matrix1.GetLength(0);
        int cols1 = matrix1.GetLength(1);
        int rows2 = matrix2.GetLength(0);
        int cols2 = matrix2.GetLength(1);
        if (cols1 != rows2)
        {
            throw new ArgumentException("Matrix dimensions are not compatible for multiplication.");
        }
        double[,] result = new double[rows1, cols2];
        for (int i = 0; i < rows1; i++)
        {
            for (int j = 0; j < cols2; j++)
            {
                double sum = 0;
                for (int k = 0; k < cols1; k++)
                {
                    sum += matrix1[i, k] * matrix2[k, j];
                }
                result[i, j] = sum;
            }
        }
        return result;
    }
    public static double[] Solve(double[,] A, double[] B)
    {
        int n = B.Length;
        for (int i = 0; i < n; i++)
        {
            double max = Math.Abs(A[i, i]);
            int maxIndex = i;
            for (int j = i + 1; j < n; j++)
            {
                if (Math.Abs(A[j, i]) > max)
                {
                    max = Math.Abs(A[j, i]);
                    maxIndex = j;
                }
            }
            for (int j = i; j < n; j++)
            {
                double temp = A[i, j];
                A[i, j] = A[maxIndex, j];
                A[maxIndex, j] = temp;
            }
            double temp2 = B[i];
            B[i] = B[maxIndex];
            B[maxIndex] = temp2;
            for (int j = i + 1; j < n; j++)
            {
                double factor = A[j, i] / A[i, i];
                for (int k = i; k < n; k++)
                {
                    A[j, k] -= factor * A[i, k];
                }
                B[j] -= factor * B[i];
            }
        }
        double[] X = new double[n];
        for (int i = n - 1; i >= 0; i--)
        {
            double sum = 0;
            for (int j = i + 1; j < n; j++)
            {
                sum += A[i, j] * X[j];
            }
            X[i] = (B[i] - sum) / A[i, i];
        }
        return X;
    }
}
```
This code uses matrix operations to solve the system of equations that determines the coefficients of the polynomial equation. The `Transpose` method transposes a matrix, the `Multiply` method multiplies two matrices, and the `Solve` method solves a system of linear equations using Gaussian elimination.
