```
function calculateMonthlyPayment(principal, interestRate, loanTerm, propertyTaxRate, insuranceRate, otherExpenses) {
  const monthlyInterestRate = interestRate / 12;
  const numberOfPayments = loanTerm * 12;
  const propertyTax = (propertyTaxRate / 100) * principal / 12;
  const insurance = (insuranceRate / 100) * principal / 12;
  const totalExpenses = propertyTax + insurance + otherExpenses;
  const monthlyPayment = (principal * monthlyInterestRate) / (1 - Math.pow(1 + monthlyInterestRate, -numberOfPayments));
  const totalMonthlyPayment = monthlyPayment + totalExpenses;
  return totalMonthlyPayment.toFixed(2);
}
// Example usage:
