```python
import nltk
import random
# Download and load the corpus
nltk.download('punkt')
corpus = nltk.corpus.gutenberg.words('blake-poems.txt')
# Create a dictionary of word pairs with their frequency counts
word_pairs = {}
for i in range(len(corpus)-1):
    if corpus[i].isalpha() and corpus[i+1].isalpha():
        pair = (corpus[i].lower(), corpus[i+1].lower())
        if pair in word_pairs:
            word_pairs[pair] += 1
        else:
            word_pairs[pair] = 1
# Create a dictionary of starting words with their frequency counts
start_words = {}
for pair in word_pairs:
    if pair[0] == '.':
        if pair[1] in start_words:
            start_words[pair[1]] += 1
        else:
            start_words[pair[1]] = 1
# Generate a poem
poem = ''
current_word = random.choice(list(start_words.keys()))
while len(poem) < 100:
    poem += current_word + ' '
    next_words = []
    for pair in word_pairs:
        if pair[0] == current_word:
            next_words.append(pair[1])
    if len(next_words) > 0:
        current_word = random.choice(next_words)
    else:
        current_word = random.choice(list(start_words.keys()))
poem = poem.capitalize().strip() + '.'
print(poem)
```
