```go
package main
import (
	"database/sql"
	"fmt"
	"html/template"
	"log"
	_ "github.com/denisenkom/go-mssqldb"
)
type Metrics struct {
	Traffic        int
	ConversionRate float32
	AverageOrder   float32
	Feedback       string
}
func main() {
	connString := "server=localhost;database=mydatabase;user id=myuser;password=mypassword"
	db, err := sql.Open("mssql", connString)
	if err != nil {
		log.Fatal("Error opening connection:", err.Error())
	}
	defer db.Close()
	rows, err := db.Query("SELECT traffic, conversion_rate, avg_order_value, feedback FROM metrics")
	if err != nil {
		log.Fatal("Error retrieving data:", err.Error())
	}
	defer rows.Close()
	var metrics []Metrics
	for rows.Next() {
		var m Metrics
		err := rows.Scan(&m.Traffic, &m.ConversionRate, &m.AverageOrder, &m.Feedback)
		if err != nil {
			log.Fatal("Error scanning row:", err.Error())
		}
		metrics = append(metrics, m)
	}
	tmpl, err := template.ParseFiles("report.html")
	if err != nil {
		log.Fatal("Error parsing template:", err.Error())
	}
	report, err := os.Create("report.html")
	if err != nil {
		log.Fatal("Error creating report file:", err.Error())
	}
	defer report.Close()
	err = tmpl.Execute(report, metrics)
	if err != nil {
		log.Fatal("Error generating report:", err.Error())
	}
	fmt.Println("Report generated successfully.")
}
