Here are the three laws of motion and their corresponding code implementations in Swift:
**First Law of Motion:** An object at rest will remain at rest, and an object in motion will remain in motion at a constant velocity, unless acted upon by an external force.
```swift
class Object {
    var isResting: Bool = true
    var velocity: Double = 0.0

    func applyForce(force: Double) {
        if isResting {
            isResting = false
        }
        velocity += force
    }
}
let object = Object()
print(object.isResting) // true
object.applyForce(force: 10.0)
print(object.isResting) // false
print(object.velocity) // 10.0
```
**Second Law of Motion:** The acceleration of an object is directly proportional to the force applied to it and inversely proportional to its mass.
```swift
class Object {
    var mass: Double = 1.0
    var acceleration: Double = 0.0

    func applyForce(force: Double) {
        acceleration = force / mass
    }
}
let object = Object()
print(object.acceleration) // 0.0
object.applyForce(force: 10.0)
print(object.acceleration) // 10.0
```
**Third Law of Motion:** For every action, there is an equal and opposite reaction.
```swift
class Object {
    var force: Double = 0.0

    func applyForce(force: Double) {
        self.force = force
    }
}
let object1 = Object()
let object2 = Object()
object1.applyForce(force: 10.0)
print(object1.force) // 10.0
print(object2.force) // 0.0
object2.applyForce(force: -10.0)
print(object1.force) // 10.0
print(object2.force) // -10.0
```
