```
using System;
using System.IO;
using NodaTime;
class Program
{
    static void Main(string[] args)
    {
        LocalDate startDate = new LocalDate(2022, 1, 1); // Change this to your desired start date
        LocalDate endDate = startDate.PlusDays(27); // 28-day lunar cycle
        string poem = "The moon, so bright,\nA pearl in the night,\nA mystery in sight,\nA wonder of light."; // Change this to your desired poem
        // Create table header
        string table = "\\begin{tabular}{|c|c|p{7cm}|}\n";
        table += "\\hline\n";
        table += "Day & Moon Phase & Description \\\\ \n";
        table += "\\hline\n";
        // Calculate moon phase for each day and add to table
        for (LocalDate date = startDate; date <= endDate; date = date.PlusDays(1))
        {
            MoonPhase moonPhase = MoonPhaseCalculator.CalculateMoonPhase(date);
            string phaseName = MoonPhaseCalculator.GetMoonPhaseName(moonPhase);
            string description = MoonPhaseCalculator.GetMoonPhaseDescription(moonPhase);
            table += $"{date.DayOfWeek} {date.Day} & {phaseName} & {description} \\\\ \n";
            table += "\\hline\n";
        }
        // Create Latex document
        string latex = $"\\documentclass{{article}}\n\\begin{{document}}\n{table}\\end{{tabular}}\n\n{poem}\n\\end{{document}}";
        // Save Latex document to file
        string filePath = "lunar_cycle.tex"; // Change this to your desired file path
        File.WriteAllText(filePath, latex);
    }
}
public static class MoonPhaseCalculator
{
    public static MoonPhase CalculateMoonPhase(LocalDate date)
    {
        double daysSinceNewMoon = (date - new LocalDate(2000, 1, 6)).TotalDays;
        double synodicMonth = 29.530588; // Average length of a synodic month in days
        double moonPhase = (daysSinceNewMoon % synodicMonth) / synodicMonth;
        return (MoonPhase)Math.Floor(moonPhase * 8);
    }
    public static string GetMoonPhaseName(MoonPhase moonPhase)
    {
        switch (moonPhase)
        {
            case MoonPhase.NewMoon:
                return "New Moon";
            case MoonPhase.WaxingCrescent:
                return "Waxing Crescent";
            case MoonPhase.FirstQuarter:
                return "First Quarter";
            case MoonPhase.WaxingGibbous:
                return "Waxing Gibbous";
            case MoonPhase.FullMoon:
                return "Full Moon";
            case MoonPhase.WaningGibbous:
                return "Waning Gibbous";
            case MoonPhase.ThirdQuarter:
                return "Third Quarter";
            case MoonPhase.WaningCrescent:
                return "Waning Crescent";
            default:
                return "";
        }
    }
    public static string GetMoonPhaseDescription(MoonPhase moonPhase)
    {
        switch (moonPhase)
        {
            case MoonPhase.NewMoon:
                return "The moon is not visible in the sky.";
            case MoonPhase.WaxingCrescent:
                return "The moon is a thin crescent in the western sky after sunset.";
            case MoonPhase.FirstQuarter:
                return "The moon is half illuminated and rises around noon, sets around midnight.";
            case MoonPhase.WaxingGibbous:
                return "The moon is more than half illuminated and rises in the afternoon, sets in the morning.";
            case MoonPhase.FullMoon:
                return "The moon is fully illuminated and rises at sunset, sets at sunrise.";
            case MoonPhase.WaningGibbous:
                return "The moon is more than half illuminated and rises in the evening, sets in the morning.";
            case MoonPhase.ThirdQuarter:
                return "The moon is half illuminated and rises around midnight, sets around noon.";
            case MoonPhase.WaningCrescent:
                return "The moon is a thin crescent in the eastern sky before sunrise.";
            default:
                return "";
        }
    }
}
public enum MoonPhase
{
    NewMoon,
    WaxingCrescent,
    FirstQuarter,
    WaxingGibbous,
    FullMoon,
    WaningGibbous,
    ThirdQuarter,
    WaningCrescent
}
```
