```scala
import akka.actor.{ Actor, ActorRef, ActorSystem, Props }
case object ReduceWorkHours
class BusyIndividual extends Actor {
  var workHours: Int = 8
  def receive = {
    case ReduceWorkHours => {
      workHours -= 1
      println(s"Reduced work hours to $workHours")
    }
  }
}
object Main extends App {
  val system = ActorSystem("BusyIndividualSystem")
  val busyIndividual = system.actorOf(Props[BusyIndividual], "busyIndividual")
  busyIndividual ! ReduceWorkHours
  busyIndividual ! ReduceWorkHours
  busyIndividual ! ReduceWorkHours
}
```
