To modify the Swift code to change singular nouns to their irregular plural forms, you can use a natural language processing library such as NLTK or Spacy. These libraries have built-in functions to identify the part of speech of each word in a sentence and can be used to identify singular nouns.
To optimize the code to handle a larger number of nouns with ease, you can create a dictionary of irregular plural forms of common singular nouns and use it to replace the singular nouns in the sentence.
Here's an example of how the Swift code can be modified to achieve this:
```
import NaturalLanguage
let sentence = "During my morning commute to work, I had the pleasure of encountering not one, but two stunning animals: a regal stag and a splendid elk."
let tagger = NLTagger(tagSchemes: [.lexicalClass])
tagger.string = sentence
let options: NLTagger.Options = [.omitWhitespace, .omitPunctuation, .joinNames]
var modifiedSentence = ""
tagger.enumerateTags(in: sentence.startIndex..<sentence.endIndex, unit: .word, scheme: .lexicalClass, options: options) { tag, range in
    guard let tag = tag else { return true }
    let word = String(sentence[range])
    switch tag {
    case .noun:
        if let pluralForm = irregularPlurals[word] {
            modifiedSentence += pluralForm
        } else if let pluralForm = NSLinguisticTagger(tagSchemes: [.lemma], options: 0).tag(at: sentence.startIndex, scheme: .lemma, tokenRange: range, sentenceRange: nil)?.rawValue, pluralForm != word {
            modifiedSentence += pluralForm
        } else {
            modifiedSentence += word
        }
    default:
        modifiedSentence += word
    }
    return true
}
let irregularPlurals = [
    "animal": "animals",
    "stag": "stags",
    "elk": "elk"
]
print(modifiedSentence)
```
